const body = $input.first().json.body ?? $input.first().json;
const currentLead = body.currentLead ?? body.fallback?.lead ?? {};
const latestUserMessage = [...(body.messages ?? [])].reverse().find((message) => message.role === 'user')?.content ?? '';

const score = Number(currentLead.confidence ?? 0);
const hasSchedulingIntent = Boolean(currentLead.schedulingIntent) || /agend|cita|consulta|whatsapp|llamar|reunion/i.test(latestUserMessage);
const temperature = hasSchedulingIntent || score >= 70 ? 'caliente' : score >= 40 ? 'tibio' : 'frio';
const phase = hasSchedulingIntent || temperature === 'caliente' ? 'agendamiento' : (body.fallback?.phase ?? 'orientacion_inicial');

const lead = {
  ...currentLead,
  temperature,
  schedulingIntent: hasSchedulingIntent,
  confidence: Math.max(score, temperature === 'caliente' ? 75 : temperature === 'tibio' ? 45 : 20),
};

const profile = lead.role && lead.role !== 'desconocido' ? lead.role : 'perfil por confirmar';
const topic = lead.caseType && lead.caseType !== 'otro' ? lead.caseType.replaceAll('_', ' ') : 'consulta laboral';
const city = lead.city ? ` en ${lead.city}` : '';
const nextQuestion = lead.phone ? '' : '\n\nSi quieres que el equipo te contacte mas facil, dejame tu nombre y celular o pasa directo a WhatsApp.';

return [{
  json: {
    reply: `Te entiendo. Ya tengo ubicado el caso como ${topic}, desde el perfil de ${profile}${city}.\n\nLa mejor ruta ahora es que un abogado laboral revise fechas, documentos y pruebas antes de que tomes decisiones. Voy a dejar el resumen listo para WhatsApp y asi no tienes que repetir todo desde cero.${nextQuestion}`,
    phase,
    quickReplies: ['Quiero agendar consulta', 'Tengo documentos', 'Necesito hablar con abogado', 'Quiero seguir contando el caso'],
    lead,
  },
}];
